mapper.select:
select id, article_id, user_id, user_ip, create_time
from blog_article_favorite
where article_id = #{articleId}


        and user_id = #{userId}


        and user_id is null
        and user_ip = #{userIp}


limit 1

mapper.delete:
delete from blog_article_favorite
where article_id = #{articleId}


        and user_id = #{userId}


        and user_id is null
        and user_ip = #{userIp}

mapper.update:
update blog_article
set favorite_count = greatest(0, ifnull(favorite_count, 0) + #{increment})
where article_id = #{articleId}
